using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient.
/// The SDK injects constructor parameters (HttpClient, ILogger) via DI —
/// they never appear in the tool schema shown to the LLM.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool, Description("List all items from the API. Returns JSON array.")]
    public async Task<string> ListItems(
        [Description("Maximum number of items to return (1-100)")] int limit = 20,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Listing items with limit {Limit}", limit);
        var response = await httpClient.GetStringAsync($"/items?limit={limit}", cancellationToken);
        return response;
    }

    [McpServerTool, Description("Get a single item by its unique identifier.")]
    public async Task<string> GetItem(
        [Description("The unique identifier of the item to retrieve")] string id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Getting item {Id}", id);
        var response = await httpClient.GetAsync($"/items/{id}", cancellationToken);

        if (!response.IsSuccessStatusCode)
        {
            return $"Error: {response.StatusCode} — item '{id}' not found.";
        }

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }

    [McpServerTool(Destructive = false, ReadOnly = false),
     Description("Create a new item with the given name and description.")]
    public async Task<string> CreateItem(
        [Description("Name for the new item")] string name,
        [Description("Optional description of the item")] string? description = null,
        CancellationToken cancellationToken = default)
    {
        var payload = new { name, description };
        var json = JsonSerializer.Serialize(payload, JsonOptions);
        var content = new StringContent(json, Encoding.UTF8, "application/json");

        logger.LogInformation("Creating item {Name}", name);
        var response = await httpClient.PostAsync("/items", content, cancellationToken);
        response.EnsureSuccessStatusCode();

        var result = await response.Content.ReadAsStringAsync(cancellationToken);
        return result;
    }

    [McpServerTool, Description("Search items by a query string.")]
    public async Task<string> SearchItems(
        [Description("Search query to filter items")] string query,
        [Description("Maximum results to return (1-50)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching items: {Query}", query);
        var encoded = Uri.EscapeDataString(query);
        var response = await httpClient.GetStringAsync(
            $"/items/search?q={encoded}&limit={limit}", cancellationToken);
        return response;
    }
}

